<?php
 namespace Pterodactyl\Http\Controllers\Dezerx; use Throwable; use Illuminate\Http\Request; use Illuminate\Http\Response; use Pterodactyl\Facades\Activity; use Illuminate\Http\RedirectResponse; use Illuminate\Support\Facades\Crypt; use Pterodactyl\Http\Controllers\Controller; use Pterodactyl\Services\Dezerx\DiscordBot\Linker; use Pterodactyl\Services\Dezerx\DiscordBot\BotConfig; use Pterodactyl\Services\Dezerx\DiscordBot\DiscordRest; use Symfony\Component\HttpKernel\Exception\NotFoundHttpException; class DiscordBotOAuthController extends Controller { private const STATE_TTL = 900; public function __construct(private DiscordRest $rest, private Linker $linker) { } public function connect(Request $request): RedirectResponse { $user = $request->user(); $bot = BotConfig::enabled() && !BotConfig::personal() ? BotConfig::globalBot() : null; if ($user === null || $bot === null || !$bot->canOAuth()) { throw new NotFoundHttpException(); } $state = Crypt::encryptString(implode('|', [$user->id, $bot->uuid, time(), bin2hex(random_bytes(8))])); return redirect()->away('https://discord.com/oauth2/authorize?' . http_build_query([ 'client_id' => $bot->application_id, 'redirect_uri' => BotConfig::oauthRedirect(), 'response_type' => 'code', 'scope' => 'identify', 'state' => $state, 'prompt' => 'consent', ])); } public function callback(Request $request): Response { try { [$userId, $botUuid, $issued] = explode('|', Crypt::decryptString((string) $request->query('state', '')), 4); } catch (Throwable) { return $this->finish('failed'); } $user = $request->user(); if ($user === null || (int) $userId !== (int) $user->id) { return $this->finish('mismatch'); } if (time() - (int) $issued > self::STATE_TTL) { return $this->finish('failed'); } $bot = BotConfig::enabled() && !BotConfig::personal() ? BotConfig::globalBot() : null; if ($bot === null || $bot->uuid !== $botUuid || !$bot->canOAuth()) { return $this->finish('failed'); } $code = (string) $request->query('code', ''); if ($code === '') { return $this->finish('cancelled'); } $token = $this->rest->exchange($bot, $code, BotConfig::oauthRedirect()); $identity = $token === null ? null : $this->rest->identity($token); if ($identity === null) { return $this->finish('failed'); } $result = $this->linker->link($user, $identity); if (!$result['ok']) { return $this->finish($result['status']); } Activity::event('user:discord-bot.link')->property('discord', $identity['username'])->log(); return $this->finish('connected', $identity['username']); } private function finish(string $status, ?string $username = null): Response { return response()->view('dezerx.discord', [ 'status' => $status, 'username' => $username, 'origin' => url('/'), ]); } } 